# Ping-pong API

Small TypeScript HTTP API with no runtime dependencies.

## Run locally

```bash
npm install
npm run dev
```

The server listens on port `3000` by default. Set `PORT` or `HOST` to change
the binding.

## Endpoint

```bash
curl http://localhost:3000/ping
# {"message":"pong"}
```

Only `GET /ping` is supported. Unknown routes return `404`, and other methods
on `/ping` return `405`.

## Verify

```bash
npm test
```
import type { IncomingMessage, ServerResponse } from "node:http";

type JsonResponse = Record<string, string>;

function sendJson(
  response: ServerResponse,
  statusCode: number,
  body: JsonResponse,
): void {
  const payload = JSON.stringify(body);

  response.writeHead(statusCode, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(payload),
  });
  response.end(payload);
}

export function requestHandler(
  request: IncomingMessage,
  response: ServerResponse,
): void {
  const requestUrl = new URL(
    request.url ?? "/",
    `http://${request.headers.host ?? "localhost"}`,
  );

  if (requestUrl.pathname === "/ping") {
    if (request.method !== "GET") {
      response.setHeader("Allow", "GET");
      sendJson(response, 405, { error: "Method Not Allowed" });
      return;
    }

    sendJson(response, 200, { message: "pong" });
    return;
  }

  sendJson(response, 404, { error: "Not Found" });
}
import assert from "node:assert/strict";
import { createServer } from "node:http";
import { once } from "node:events";
import test from "node:test";
import { requestHandler } from "../dist/app.js";

async function startTestServer() {
  const server = createServer(requestHandler);
  server.listen(0, "127.0.0.1");
  await once(server, "listening");

  const address = server.address();
  if (address === null || typeof address === "string") {
    throw new Error("Could not determine test server address");
  }

  return { server, url: `http://127.0.0.1:${address.port}` };
}

test("GET /ping returns pong", async (t) => {
  const { server, url } = await startTestServer();
  t.after(() => server.close());

  const response = await fetch(`${url}/ping`);

  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { message: "pong" });
  assert.match(response.headers.get("content-type"), /application\/json/);
});

test("unknown routes return 404", async (t) => {
  const { server, url } = await startTestServer();
  t.after(() => server.close());

  const response = await fetch(`${url}/unknown`);

  assert.equal(response.status, 404);
  assert.deepEqual(await response.json(), { error: "Not Found" });
});

